10→// CommittedReader provides read access to committed checkpoint data.
11→// Both GitStore (v1) and V2GitStore (v2) implement this interface.
12→type CommittedReader interface {
13→	ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)
14→	ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
15→}
