17→// ResolveCommittedReaderForCheckpoint resolves which committed checkpoint reader
18→// should be used for a specific checkpoint ID.
19→//
20→// Fallback behavior mirrors resume/rewind patterns:
21→//   - Try v2 first when preferCheckpointsV2 is true
22→//   - Fall back to v1 when v2 returns nil summary, ErrCheckpointNotFound, or ErrNoTranscript
23→//   - Propagate other v2 errors without fallback
24→func ResolveCommittedReaderForCheckpoint(
25→	ctx context.Context,
26→	checkpointID id.CheckpointID,
27→	v1Store *GitStore,
28→	v2Store *V2GitStore,
29→	preferCheckpointsV2 bool,
30→) (CommittedReader, *CheckpointSummary, error) {
31→	if err := ctx.Err(); err != nil {
32→		return nil, nil, err //nolint:wrapcheck // Propagating context cancellation
33→	}
34→
35→	if preferCheckpointsV2 && v2Store != nil {
36→		summary, err := v2Store.ReadCommitted(ctx, checkpointID)
37→		if err == nil && summary != nil {
38→			return v2Store, summary, nil
39→		}
40→		if err != nil && !errors.Is(err, ErrCheckpointNotFound) && !errors.Is(err, ErrNoTranscript) {
41→			return nil, nil, err
42→		}
43→	}
44→
45→	if v1Store == nil {
46→		return nil, nil, ErrCheckpointNotFound
47→	}
48→
49→	summary, err := v1Store.ReadCommitted(ctx, checkpointID)
50→	if err != nil {
51→		return nil, nil, err
52→	}
53→	if summary == nil {
54→		return nil, nil, ErrCheckpointNotFound
55→	}
56→
57→	return v1Store, summary, nil
58→}
