207→// runExplainCheckpoint explains a specific checkpoint.
208→// Supports both committed checkpoints (by checkpoint ID) and temporary checkpoints (by git SHA).
209→// First tries to match committed checkpoints, then falls back to temporary checkpoints.
210→// When generate is true, generates an AI summary for the checkpoint.
211→// When force is true, regenerates even if a summary already exists.
212→// When rawTranscript is true, outputs only the raw transcript file (JSONL format).
213→// When searchAll is true, searches all commits without branch/depth limits (used for finding associated commits).
214→func runExplainCheckpoint(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool) error {
215→	repo, err := openRepository(ctx)
216→	if err != nil {
217→		return fmt.Errorf("not a git repository: %w", err)
218→	}
219→
220→	v1Store := checkpoint.NewGitStore(repo)
221→	v2Store := checkpoint.NewV2GitStore(repo, strategy.ResolveCheckpointURL(ctx, "origin"))
222→	preferCheckpointsV2 := settings.IsCheckpointsV2Enabled(ctx)
223→
224→	// First, try to find in committed checkpoints by checkpoint ID prefix
225→	committed, err := listCommittedForExplain(ctx, v1Store, v2Store, preferCheckpointsV2)
226→	if err != nil {
227→		return fmt.Errorf("failed to list checkpoints: %w", err)
228→	}
229→
230→	// Collect all matching checkpoint IDs to detect ambiguity
231→	var matches []id.CheckpointID
232→	for _, info := range committed {
233→		if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
234→			matches = append(matches, info.CheckpointID)
235→		}
236→	}
237→
238→	var fullCheckpointID id.CheckpointID
239→	switch len(matches) {
240→	case 0:
241→		// Not found in committed, try temporary checkpoints by git SHA
242→		if generate {
243→			return fmt.Errorf("cannot generate summary for temporary checkpoint %s (only committed checkpoints supported)", checkpointIDPrefix)
244→		}
245→		output, found := explainTemporaryCheckpoint(ctx, w, repo, v1Store, checkpointIDPrefix, verbose, full, rawTranscript)
246→		if found {
247→			outputExplainContent(w, output, noPager)
248→			return nil
249→		}
250→		// If output is non-empty, it contains an error message (e.g., ambiguous prefix)
251→		if output != "" {
252→			return errors.New(output)
253→		}
254→		return fmt.Errorf("checkpoint not found: %s", checkpointIDPrefix)
255→	case 1:
256→		fullCheckpointID = matches[0]
257→	default:
258→		// Ambiguous prefix - show up to 5 examples
259→		examples := make([]string, 0, 5)
260→		for i := 0; i < len(matches) && i < 5; i++ {
261→			examples = append(examples, matches[i].String())
262→		}
263→		return fmt.Errorf("ambiguous checkpoint prefix %q matches %d checkpoints: %s", checkpointIDPrefix, len(matches), strings.Join(examples, ", "))
264→	}
265→
266→	// Resolve store and load checkpoint summary with v2 -> v1 fallback.
267→	resolvedReader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, fullCheckpointID, v1Store, v2Store, preferCheckpointsV2)
268→	if err != nil {
269→		return fmt.Errorf("failed to read checkpoint: %w", err)
270→	}
271→
272→	// Load latest session content (needed for transcript and metadata)
273→	content, err := readLatestSessionContentForExplain(ctx, resolvedReader, fullCheckpointID, summary)
274→	if err != nil {
275→		return fmt.Errorf("failed to read checkpoint content: %w", err)
276→	}
277→
278→	// Handle summary generation — uses raw transcript (before compact override).
279→	if generate {
280→		if err := generateCheckpointSummary(ctx, w, errW, v1Store, v2Store, fullCheckpointID, summary, content, force); err != nil {
281→			return err
282→		}
283→		// Reload the content to get the updated summary
284→		content, err = readLatestSessionContentForExplain(ctx, resolvedReader, fullCheckpointID, summary)
285→		if err != nil {
286→			return fmt.Errorf("failed to reload checkpoint: %w", err)
287→		}
288→	}
289→
290→	// For v2 checkpoints, prefer compact transcript.jsonl from /main for
291→	// human-readable output (default and --short/verbose modes). Keep --full
292→	// on raw full.jsonl semantics. Placed after --generate so summarization
293→	// always receives the raw transcript.
294→	if !full {
295→		if v2Reader, ok := resolvedReader.(*checkpoint.V2GitStore); ok && len(summary.Sessions) > 0 {
296→			latestIndex := len(summary.Sessions) - 1
297→			compactTranscript, compactErr := v2Reader.ReadSessionCompactTranscript(ctx, fullCheckpointID, latestIndex)
298→			if compactErr == nil && len(compactTranscript) > 0 {
299→				content.Transcript = compactTranscript
300→				content.Metadata.CheckpointTranscriptStart = 0
301→				content.Metadata.TranscriptLinesAtStart = 0 //nolint:staticcheck // Set for backward compat with older CLI readers
302→			} else if compactErr != nil && !errors.Is(compactErr, checkpoint.ErrNoTranscript) && !errors.Is(compactErr, checkpoint.ErrCheckpointNotFound) {
303→				logging.Debug(ctx, "failed to read compact transcript, using raw transcript",
304→					slog.String("checkpoint_id", fullCheckpointID.String()),
305→					slog.String("error", compactErr.Error()),
306→				)
307→			}
308→		}
309→	}
310→
311→	// Handle raw transcript output
312→	if rawTranscript {
313→		rawLog, _, rawErr := checkpoint.ResolveRawSessionLogForCheckpoint(ctx, fullCheckpointID, v1Store, v2Store, preferCheckpointsV2)
314→		if rawErr != nil {
315→			return fmt.Errorf("failed to read raw transcript: %w", rawErr)
316→		}
317→		if len(rawLog) == 0 {
318→			return fmt.Errorf("checkpoint %s has no transcript", fullCheckpointID)
319→		}
320→		// Output raw transcript directly (no pager, no formatting)
321→		if _, err = w.Write(rawLog); err != nil {
322→			return fmt.Errorf("failed to write transcript: %w", err)
323→		}
324→		return nil
325→	}
326→
327→	// Find associated commits (git commits with matching Entire-Checkpoint trailer)
328→	associatedCommits, _ := getAssociatedCommits(ctx, repo, fullCheckpointID, searchAll) //nolint:errcheck // Best-effort
329→
330→	// Derive author from the first associated commit (the user who made the commit).
331→	// Fall back to GetCheckpointAuthor (walks entire/checkpoints/v1) for checkpoints
332→	// not reachable from the current branch.
333→	var author checkpoint.Author
334→	if len(associatedCommits) > 0 {
335→		author = checkpoint.Author{
336→			Name:  associatedCommits[0].Author,
337→			Email: associatedCommits[0].Email,
338→		}
339→	} else {
340→		author, _ = v1Store.GetCheckpointAuthor(ctx, fullCheckpointID) //nolint:errcheck // Author is optional
341→	}
342→
343→	// Format and output
344→	output := formatCheckpointOutput(summary, content, fullCheckpointID, associatedCommits, author, verbose, full)
345→	outputExplainContent(w, output, noPager)
346→	return nil
347→}
