349→func listCommittedForExplain(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, preferCheckpointsV2 bool) ([]checkpoint.CommittedInfo, error) {
350→	v1Committed, v1Err := v1Store.ListCommitted(ctx)
351→
352→	if !preferCheckpointsV2 {
353→		if v1Err != nil {
354→			return nil, fmt.Errorf("listing v1 checkpoints: %w", v1Err)
355→		}
356→		return v1Committed, nil
357→	}
358→
359→	v2Committed, v2Err := v2Store.ListCommitted(ctx)
360→	if v2Err != nil {
361→		logging.Debug(ctx, "v2 ListCommitted failed, using v1 only",
362→			slog.String("error", v2Err.Error()),
363→		)
364→		if v1Err != nil {
365→			return nil, fmt.Errorf("listing checkpoints: %w", v1Err)
366→		}
367→		return v1Committed, nil
368→	}
369→
370→	if v1Err != nil {
371→		logging.Debug(ctx, "v1 ListCommitted failed, returning v2 only",
372→			slog.String("error", v1Err.Error()),
373→		)
374→		return v2Committed, nil
375→	}
376→
377→	// Merge: start with v2, add v1-only entries so pre-v2 checkpoints
378→	// remain visible during the transition period.
379→	merged := v2Committed
380→	seen := make(map[id.CheckpointID]struct{}, len(merged))
381→	for _, c := range merged {
382→		seen[c.CheckpointID] = struct{}{}
383→	}
384→	for _, c := range v1Committed {
385→		if _, ok := seen[c.CheckpointID]; !ok {
386→			merged = append(merged, c)
387→		}
388→	}
389→	return merged, nil
390→}
