189→// on /full/current while preserving other checkpoints' transcripts in the tree.
190→func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
191→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
192→	if err := s.ensureRef(refName); err != nil {
193→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
194→	}
195→
196→	parentHash, rootTreeHash, err := s.GetRefState(refName)
197→	if err != nil {
198→		return err
199→	}
200→
201→	basePath := opts.CheckpointID.Path() + "/"
202→	checkpointPath := opts.CheckpointID.Path()
203→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
204→
205→	// Read existing entries and replace transcript for this checkpoint only
206→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
207→	if err != nil {
208→		return err
209→	}
210→
211→	// Clear existing transcript entries at this session path before writing new ones
212→	for key := range entries {
213→		if strings.HasPrefix(key, sessionPath) {
214→			delete(entries, key)
215→		}
216→	}
217→
218→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, sessionPath, entries)
219→	if err != nil {
220→		return err
221→	}
222→
223→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
224→		return err
225→	}
226→
227→	// Splice into existing root tree (preserves other checkpoints' transcripts)
228→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
229→	if err != nil {
230→		return err
231→	}
232→
233→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
234→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
235→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
236→}
