233→	transcript, transcriptErr := s.readTranscriptFromFullRefs(ctx, checkpointID, sessionIndex, result.Metadata.Agent)
234→	if transcriptErr != nil {
235→		return nil, fmt.Errorf("failed to read transcript from /full/* refs: %w", transcriptErr)
