245→// readTranscriptFromFullRefs reads the raw transcript for a checkpoint session
246→// by searching /full/current first, then archived generations in reverse order.
247→// If not found locally, attempts to discover and fetch remote /full/* refs.
248→func (s *V2GitStore) readTranscriptFromFullRefs(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, agentType types.AgentType) ([]byte, error) {
249→	if err := ctx.Err(); err != nil {
250→		return nil, err //nolint:wrapcheck // Propagating context cancellation
251→	}
252→
253→	sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)
254→
255→	// Search locally first
256→	transcript, err := s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
257→	if err == nil && len(transcript) > 0 {
258→		return transcript, nil
259→	}
260→
261→	archived, err := s.ListArchivedGenerations()
262→	if err != nil {
263→		return nil, err
264→	}
265→	for i := len(archived) - 1; i >= 0; i-- {
266→		refName := plumbing.ReferenceName(paths.V2FullRefPrefix + archived[i])
267→		transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
268→		if err == nil && len(transcript) > 0 {
269→			return transcript, nil
270→		}
271→	}
272→
273→	// Not found locally — try fetching remote /full/* refs
274→	if fetchErr := s.fetchRemoteFullRefs(ctx); fetchErr != nil {
275→		logging.Debug(ctx, "failed to fetch remote /full/* refs",
276→			slog.String("error", fetchErr.Error()),
277→		)
278→		return nil, nil
279→	}
280→
281→	// Search newly fetched refs only
282→	newArchived, err := s.ListArchivedGenerations()
283→	if err != nil {
284→		return nil, nil //nolint:nilerr // Best-effort: fetch-on-demand failure shouldn't block resume
285→	}
286→	existingSet := make(map[string]bool, len(archived))
287→	for _, a := range archived {
288→		existingSet[a] = true
289→	}
290→	for i := len(newArchived) - 1; i >= 0; i-- {
291→		if existingSet[newArchived[i]] {
292→			continue
293→		}
294→		refName := plumbing.ReferenceName(paths.V2FullRefPrefix + newArchived[i])
295→		transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
296→		if err == nil && len(transcript) > 0 {
297→			return transcript, nil
298→		}
299→	}

