// recoverV2ContentFromMain builds SessionContent from the v2 /main ref when the
// raw transcript (/full/*) is unavailable. Uses metadata+prompts plus the compact
// transcript (transcript.jsonl) from /main as a substitute for display modes that
// don't require the raw transcript.
func recoverV2ContentFromMain(ctx context.Context, v2Reader *checkpoint.V2GitStore, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) (*checkpoint.SessionContent, error) {
	if summary == nil || len(summary.Sessions) == 0 {
		return nil, checkpoint.ErrCheckpointNotFound
	}

	latestIndex := len(summary.Sessions) - 1

	content, err := v2Reader.ReadSessionMetadataAndPrompts(ctx, checkpointID, latestIndex)
	if err != nil {
		return nil, fmt.Errorf("reading session %d metadata: %w", latestIndex, err)
	}

	compactTranscript, compactErr := v2Reader.ReadSessionCompactTranscript(ctx, checkpointID, latestIndex)
	if compactErr != nil || len(compactTranscript) == 0 {
		return nil, checkpoint.ErrNoTranscript
	}

	content.Transcript = compactTranscript
	content.Metadata.CheckpointTranscriptStart = 0
	content.Metadata.TranscriptLinesAtStart = 0 //nolint:staticcheck // Set for backward compat with older CLI readers

	logging.Debug(ctx, "recovered v2 explain content from /main (no raw transcript)",
		slog.String("checkpoint_id", checkpointID.String()),
	)

	return content, nil
}

// generateCheckpointSummary generates an AI summary for a checkpoint and persists it.
// The summary is generated from the scoped transcript (only this checkpoint's portion),
// not the entire session transcript.

